const showStatusHTML = async (status) => {
  setTimeout(() => {
    console.log("status", status);
    switch (status) {
      case "Unpaid":
        this.display(["unpaid_status"]);
        break;
      case "Partial":
        this.display(["partial_status"]);
        break;
      case "Paid":
        this.display(["paid_status"]);
        break;
      case "Cancelled":
        this.display(["cancelled_status"]);
        break;
      default:
        break;
    }
  }, 300);
};

(async () => {
  try {
    const status = await this.getValue("payment_status");

    let pageStatus = "";

    if (this.isAdd) pageStatus = "Add";
    else if (this.isEdit) pageStatus = "Edit";
    else if (this.isView) pageStatus = "View";
    else if (this.isCopy) pageStatus = "Clone";
    else throw new Error("Invalid page state");

    console.log("pageStatus", pageStatus);

    switch (pageStatus) {
      case "Add":
        break;

      case "Edit":
        break;

      case "Clone":
        break;

      case "View":
        await showStatusHTML(status);
        break;
    }
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

setTimeout(async () => {
  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible("ar_invoice_no_type", true);
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }
  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }
  var params = this.getComponent("ar_invoice_no");
  const { options } = params;

  const optionsData = this.getOptionData("ar_invoice_no_type") || [];
  const defaultData = getDefaultItem(optionsData);
  if (options?.canManualInput) {
    this.setOptionData("ar_invoice_no_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
    if (this.isAdd) {
      this.setData({
        ar_invoice_no_type: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData) {
    if (this.isAdd) {
      this.setData({ ar_invoice_no_type: defaultData.value });
    }
  }
}, 200);

